head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.popWidth = 1287; // 상세팝업 가로 사이즈
scwin.popHeight = 670;

// 화면명

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용
        await scwin.initPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15845.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15845.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15845.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    // FillGridHeaderTotalCnt(rowcount, panel_page);    //총 건수

};

/**
 * @method
 * @name dts_year_OnLoadCompleted
 * @description dts_year 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_year_OnLoadCompleted = function(rowcount) {
    try {
        // 연도가 없다는건 실제 데이타가 없다는 것이기 때문에 별도 텍스트를 보여줌
        if (rowcount === 0) {
            dts_year.insertRow();
            dts_year.setCellData(1, "YEAR_TEXT", '연도가 존재하지 않습니다');
            dts_year.setCellData(1, "YEAR", '');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15845.dts_year_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        scwin.excel();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15845.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 기업지배구조핵심지표준수현황 상세조회
        // 클릭해야 되는 컬럼이 아닐 경우는 스킵
        if (colid !== "CORE_INDIC_COMP_DSC" && colid !== "DISCLS_PUBL_DDTM") {
            return;
        }
        // row가 0번째일 경우 스킵(타이틀을 클릭할때)
        if (row === 0) {
            return;
        }
        // 데이타가 없을 경우는 스킵
        if (colid === "CORE_INDIC_COMP_DSC") {
            if (dts_Grid.getCellData(Number(row), 'CORE_INDIC_COMP_DSC') === '') {
                return;
            }
        }
        if (colid === "DISCLS_PUBL_DDTM") {
            // 공시시각을 클릭할 경우 공시뷰어 메인창을 오픈
            const gAcptNo = dts_Grid.getCellData(Number(row), "ACPT_NO"); // 접수번호
            await $c.stf.openDisclViewer(gAcptNo, "R");
        } else {
            dtlRoleSel = 'role0-3';
            scwin.setData(dts_Grid, row, colid);
            await scwin.openPopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15845.grd_Grid_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setYear
 * @description 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setYear = async function() {
    // 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
    // ^temp 에서 temp는 의미 없는 값이지만, ^뒤에 데이타가 있어야 문구가 노출됨.
    cmb_YearList.CBData = "연도 조회중...^temp";
    // 연도조회(데이타가 등록 되어 있다면 연도가 조회 될 것이고 등록 안되어 있다면 연도가 없음)
    const sbmOptions = {
        id : "sbm_dts_year",
        action : "/EsgSearch.do",
        ref : "",
        target : "dts_year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 선택 된 연도
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 선택 된 연도
    let year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
    if (year === '') {
        await $c.win.alert("연도를 선택해주세요");
        return;
    }

    // 핵심지표 준수현황표 조회
    url += "&YEAR=" + year; // 연도

    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/EsgSearch.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description 상세팝업 세로 사이즈
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    await scwin.setYear();
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {void}
 * @hidden N
 */
scwin.excel = function() {
    $c.stf.doLogSave('ULDSTF15845.xml', SCREN_PROCS_TP_CD_07);
    // 선택한 연도(파일명에 선택한 년도를 붙임)
    let year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
    // 엑셀 다운로드
    $c.data.downloadGridViewOffice(grd_Grid, "핵심지표준수현황표", year + "년_핵심지표준수현황표.xlsx", 2 + 8, 0);
};

/**
 * @method
 * @name setData
 * @description 세부원칙별 상세조회 시 데이타 셋팅
 * @param {*} dtsObj dtsObj
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.setData = function(dtsObj, row, colid) {
    // 핵심지표 준수현황
    if (dtlRoleSel === 'role0-3') {
        if (colid === "CORE_INDIC_COMP_DSC") {
            reqElmtId = "krx-cg_ComplianceStatusWithKeyIndicatorsOfCorporateGovernanceExplanatory";
        }
    }

    // 접수번호,  엘리먼트 아이디를 조합하여 데이타를 넘긴다.
    data = dtsObj.getCellData(Number(row), 'ACPT_NO') + "^" + reqElmtId;
};

/**
 * @method
 * @name openPopup
 * @description 상세조회 팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPopup = async function() {
    // 상세조회 팝업
    const options = {
        id: "esg_viewer",
        title: "세부원칙 상세조회",
        type: "browserPopup",
        width: scwin.popWidth,
        height: scwin.popHeight,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/esg/esg_viewer.gfm", options);
};
